function obtenerValorDropdown(){const dropdown=document.querySelector("#formEliminarDefinitivamente .dropdownfiltrable .caja");if(!dropdown)return"";const textoSeleccionado=dropdown.value.trim();if(!textoSeleccionado)return"";const elementos=document.querySelectorAll("#formEliminarDefinitivamente .dropdownfiltrable .elementos span");for(let i=0;i<elementos.length;i++){const textoElemento=elementos[i].textContent.trim()||elementos[i].innerHTML.trim();if(textoElemento===textoSeleccionado){const valorId=elementos[i].getAttribute("data-valor");if(valorId!==null&&valorId!==undefined&&valorId!=="")return valorId}}return""}function confirmarEliminacionDefinitiva(){const idUsuarioHereditario=obtenerValorDropdown();if(!idUsuarioHereditario||idUsuarioHereditario==="")return alert("Debe seleccionar un usuario que herede la información antes de eliminar."),!1;const hiddenInput=document.getElementById("idUsuarioHereditario");hiddenInput&&(hiddenInput.value=idUsuarioHereditario);const modal=document.getElementById("modalConfirmarEliminacion");return modal&&(modal.style.display="flex"),!1}function confirmarEliminacion(){const hiddenInput=document.getElementById("idUsuarioHereditario"),form=document.getElementById("formEliminarDefinitivamente");hiddenInput&&form&&hiddenInput.value&&hiddenInput.value.trim()!==""?(cerrarModal(),form.submit()):alert("Error: No se ha seleccionado un usuario hereditario.")}function cerrarModal(){const modal=document.getElementById("modalConfirmarEliminacion");modal&&(modal.style.display="none")}document.addEventListener("DOMContentLoaded",function(){const form=document.getElementById("formEliminarDefinitivamente");if(form){form.addEventListener("submit",function(e){e.preventDefault();confirmarEliminacionDefinitiva()});const btnConfirmar=document.getElementById("btnConfirmarEliminacion"),btnCancelar=document.getElementById("btnCancelarEliminacion"),modal=document.getElementById("modalConfirmarEliminacion");btnConfirmar&&btnConfirmar.addEventListener("click",confirmarEliminacion);btnCancelar&&btnCancelar.addEventListener("click",cerrarModal);modal&&modal.addEventListener("click",function(e){e.target===modal&&cerrarModal()})}});